const express = require('express');
const { MongoClient } = require('mongodb');
const bcrypt = require('bcrypt');
const crypto = require('crypto');

const app = express();
app.use(express.json({ limit: '10kb' }));

let db;

const SALT_ROUNDS = 12;
const MAX_QUERY_DEPTH = 3;
const ALLOWED_COLLECTIONS = ['users', 'posts', 'comments', 'sessions'];

// Utility: deep-freeze config
const CONFIG = Object.freeze({
  maxResults: 100,
  defaultTimeout: 5000,
  allowedSortDirections: [1, -1],
  reservedFields: ['_id', '__v', 'passwordHash']
});

/**
 * Validates that a value is a safe primitive for use in queries.
 * Rejects objects to prevent operator injection.
 */
function isSafePrimitive(val) {
  if (val === null || val === undefined) return false;
  const t = typeof val;
  // Allow strings, numbers, booleans
  if (t === 'string' || t === 'number' || t === 'boolean') return true;
  // Allow arrays of primitives (for $in queries)
  if (Array.isArray(val)) {
    return val.length <= 20 && val.every(item => {
      const it = typeof item;
      return it === 'string' || it === 'number';
    });
  }
  return false;
}

/**
 * Validates field names to prevent injection via keys
 */
function isValidFieldName(field) {
  if (typeof field !== 'string') return false;
  if (field.length === 0 || field.length > 64) return false;
  if (field.startsWith('$') || field.startsWith('.')) return false;
  return /^[a-zA-Z][a-zA-Z0-9_.]*$/.test(field);
}

/**
 * Builds a query condition from validated inputs.
 * Each condition is a {field, op, value} triple.
 */
function buildCondition(field, op, value) {
  if (!isValidFieldName(field)) {
    throw new Error(`Invalid field name: ${field}`);
  }

  switch (op) {
    case 'eq':
      if (!isSafePrimitive(value)) throw new Error('Invalid value for eq');
      return { [field]: value };
    case 'ne':
      if (!isSafePrimitive(value)) throw new Error('Invalid value for ne');
      return { [field]: { $ne: value } };
    case 'gt':
    case 'gte':
    case 'lt':
    case 'lte':
      if (typeof value !== 'number') throw new Error(`Invalid value for ${op}`);
      return { [field]: { [`$${op}`]: value } };
    case 'in':
      if (!Array.isArray(value)) throw new Error('Invalid value for in');
      if (!isSafePrimitive(value)) throw new Error('Array contains invalid items');
      return { [field]: { $in: value } };
    case 'exists':
      if (typeof value !== 'boolean') throw new Error('Invalid value for exists');
      return { [field]: { $exists: value } };
    default:
      throw new Error(`Unsupported operator: ${op}`);
  }
}

/**
 * Combines multiple conditions into a compound query.
 * Supports 'and' and 'or' logical operators.
 */
function buildCompoundQuery(conditions, logic = 'and') {
  if (!Array.isArray(conditions)) {
    throw new Error('Conditions must be an array');
  }
  if (conditions.length === 0 || conditions.length > 10) {
    throw new Error('Conditions count must be between 1 and 10');
  }

  const builtConditions = conditions.map((cond, idx) => {
    if (typeof cond !== 'object' || cond === null) {
      throw new Error(`Condition ${idx} must be an object`);
    }
    // Handle nested compound queries (limited depth)
    if (cond.logic && cond.conditions) {
      return buildCompoundQuery(cond.conditions, cond.logic);
    }
    return buildCondition(cond.field, cond.op, cond.value);
  });

  if (logic === 'or') {
    return { $or: builtConditions };
  }
  return { $and: builtConditions };
}

/**
 * Validates and sanitizes sort specification
 */
function buildSort(sortSpec) {
  if (!sortSpec || typeof sortSpec !== 'object') return undefined;
  if (Array.isArray(sortSpec)) return undefined;

  const result = {};
  const keys = Object.keys(sortSpec);
  if (keys.length > 3) throw new Error('Too many sort fields');

  for (const key of keys) {
    if (!isValidFieldName(key)) throw new Error(`Invalid sort field: ${key}`);
    const dir = sortSpec[key];
    if (dir !== 1 && dir !== -1) throw new Error(`Invalid sort direction for ${key}`);
    result[key] = dir;
  }
  return result;
}

/**
 * Main query endpoint with comprehensive validation
 */
app.post('/api/query', async (req, res) => {
  try {
    const { collection, conditions, logic, sort, limit, skip } = req.body;

    // Validate collection
    if (!ALLOWED_COLLECTIONS.includes(collection)) {
      return res.status(400).json({ error: 'Invalid collection' });
    }

    // Build and validate query
    const query = buildCompoundQuery(conditions, logic);

    // Build sort
    const sortSpec = sort ? buildSort(sort) : { _id: -1 };

    // Validate pagination
    const queryLimit = Math.min(Math.max(parseInt(limit) || 20, 1), CONFIG.maxResults);
    const querySkip = Math.max(parseInt(skip) || 0, 0);

    // Execute query with projection that excludes sensitive fields
    const projection = { passwordHash: 0, __v: 0 };

    const results = await db.collection(collection)
      .find(query)
      .project(projection)
      .sort(sortSpec)
      .skip(querySkip)
      .limit(queryLimit)
      .maxTimeMS(CONFIG.defaultTimeout)
      .toArray();

    res.json({ results, count: results.length });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

/**
 * Authentication endpoint
 */
app.post('/api/auth/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid credentials format' });
    }
    if (username.length > 64 || password.length > 128) {
      return res.status(400).json({ error: 'Credentials too long' });
    }
    if (!/^[a-zA-Z0-9_@.\-]+$/.test(username)) {
      return res.status(400).json({ error: 'Invalid username format' });
    }

    const user = await db.collection('users').findOne(
      { username: username },
      { projection: { username: 1, passwordHash: 1, role: 1 } }
    );

    const DUMMY_HASH = '$2b$12$LJ3m4ys3Lz0YBnQpGqF8/.XBXKzGRHbyG8eKO5C2MJd.dLMqTaWmy';
    const hashToCompare = user ? user.passwordHash : DUMMY_HASH;

    const isValid = await bcrypt.compare(password, hashToCompare);

    if (!isValid || !user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = crypto.randomBytes(32).toString('hex');
    await db.collection('sessions').insertOne({
      userId: user._id,
      token: token,
      createdAt: new Date(),
      expiresAt: new Date(Date.now() + 3600000)
    });

    res.json({ token, username: user.username, role: user.role });
  } catch (err) {
    res.status(500).json({ error: 'Authentication failed' });
  }
});

/**
 * User registration
 */
app.post('/api/auth/register', async (req, res) => {
  try {
    const { username, password, email } = req.body;

    if (typeof username !== 'string' || typeof password !== 'string') {
      return res.status(400).json({ error: 'Invalid input format' });
    }
    if (typeof email !== 'string' || !/^[^@]+@[^@]+\.[^@]+$/.test(email)) {
      return res.status(400).json({ error: 'Invalid email' });
    }
    if (username.length < 3 || username.length > 32) {
      return res.status(400).json({ error: 'Username must be 3-32 chars' });
    }
    if (!/^[a-zA-Z0-9_]+$/.test(username)) {
      return res.status(400).json({ error: 'Invalid username characters' });
    }
    if (password.length < 8 || password.length > 128) {
      return res.status(400).json({ error: 'Password must be 8-128 chars' });
    }

    const existing = await db.collection('users').findOne({ username });
    if (existing) {
      return res.status(409).json({ error: 'Username taken' });
    }

    const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);

    await db.collection('users').insertOne({
      username,
      email,
      passwordHash,
      role: 'user',
      createdAt: new Date()
    });

    res.status(201).json({ message: 'User created' });
  } catch (err) {
    res.status(500).json({ error: 'Registration failed' });
  }
});

async function main() {
  const client = new MongoClient(process.env.MONGO_URI || 'mongodb://localhost:27017', {
    maxPoolSize: 10,
    serverSelectionTimeoutMS: 5000
  });
  await client.connect();
  db = client.db('appdb');

  app.listen(3000, '127.0.0.1', () => {
    console.log('Server running on port 3000');
  });
}

main().catch(console.error);
